#!/usr/bin/env python3
"""async-generator-pipelines.py <seed>: random strict TypeScript programs about streams: a source that waits for something outside the pipeline (an immediate, a chain of promise jobs), one to seven
layers of async generators above it (for await, yield*, next() by hand, filters, layers that yield twice, that catch, that clean up in finally) and a consumer that is suspended when the source wakes up.
Every step logs; other jobs, next ticks and immediates are queued at random places, so the log shows the order of jobs. AsyncLocalStorage stores are read in every layer."""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
R = random.Random(seed)
out = []; w = out.append
w('// generated by async-generator-pipelines.py %d' % seed)
w('import { AsyncLocalStorage } from "node:async_hooks";')
w('const storage = new AsyncLocalStorage<string>();')
w('let lines: string[] = [];')
w('const log = (s: string) => { lines.push(s + "@" + (storage.getStore() ?? "-")); };')
w('const show = (v: any): string => { try { return v === undefined ? "u" : typeof v === "object" && v !== null ? JSON.stringify(v) : String(v); } catch (e) { return "?"; } };')
w('const ticks = (name: string, n: number) => { let p: Promise<void> = Promise.resolve(); for (let i = 0; i < n; i++) p = p.then(() => log(name + i)); return p; };')
w('const later = (v: any, n: number): Promise<any> => { let p: Promise<any> = Promise.resolve(v); for (let i = 0; i < n; i++) p = p.then(x => x); return p; };')
w('const immediate = (v?: any): Promise<any> => new Promise(resolve => { setImmediate(() => resolve(v)); });')
w('const twoImmediates = (v?: any): Promise<any> => new Promise(resolve => { setImmediate(() => setImmediate(() => resolve(v))); });')
w('const thenable = (v: any, name: string) => ({ then(resolve: (x: any) => void) { log(name + " then"); resolve(v); } });')
w('const settle = async (running: Promise<any>[]) => { await Promise.allSettled(running); for (let i = 0; i < 12; i++) { await immediate(); for (let j = 0; j < 30; j++) await null; } };')
counter = [0]
def fresh(p): counter[0] += 1; return '%s%d' % (p, counter[0])
def wait():
    return R.choice(['immediate()', 'immediate()', 'immediate()', 'twoImmediates()', 'later(0, %d)' % R.randrange(1, 4), 'later(0, 1)', 'null', 'Promise.resolve(1)'])
def operand(i):
    return R.choice(['%s' % i, '%s' % i, '%s' % i, '{ v: %s }' % i, '"s" + %s' % i, '[%s]' % i, 'undefined', 'null', 'Promise.resolve(%s)' % i, 'later(%s, %d)' % (i, R.randrange(1, 3)), 'thenable(%s, "th")' % i, '%s + 0.5' % i])
def witness(tag):
    return R.choice(['', '', '', '', '', 'queueMicrotask(() => log("%s job"));' % tag, 'Promise.resolve().then(() => log("%s then"));' % tag, 'ticks("%s.", %d);' % (tag, R.randrange(1, 4)), 'log("%s");' % tag,
                     'process.nextTick(() => log("%s tick"));' % tag, 'setImmediate(() => log("%s immediate"));' % tag, 'void (async () => { await null; log("%s side"); })();' % tag])
def source():
    name = fresh('source'); n = R.randrange(1, 6); k = R.random()
    end = R.choice(['', '', '', 'return "end";', 'throw new Error("%s failed");' % name, 'await %s;' % wait()])
    if k < 0.55: body = 'for (let i = 0; i < %d; i++) { await %s; %s yield %s; %s }' % (n, wait(), witness(name + 'a'), operand('i'), witness(name + 'b'))
    elif k < 0.75: body = 'for (let i = 0; i < %d; ) { await %s; for (let k = 0; k < %d && i < %d; k++) yield i++; }' % (n + 2, wait(), R.randrange(1, 4), n + 2)
    elif k < 0.85: body = 'for (let i = 0; i < %d; i++) { const got: any = yield await %s.then(() => i); if (got !== undefined) log("%s got " + show(got)); }' % (n, 'immediate()', name)
    else: body = 'try { for (let i = 0; i < %d; i++) { await %s; yield %s; } } finally { log("%s cleans up"); %s }' % (n, wait(), operand('i'), name, R.choice(['', 'await %s;' % wait(), 'yield "late";']))
    w('async function* %s(): AsyncGenerator<any, any, any> { log("%s starts"); %s %s }' % (name, name, body, end))
    return '%s()' % name
def layer(inner):
    name = fresh('layer'); k = R.random(); t = name
    if k < 0.3: body = 'for await (const x of input) { %s yield x; %s }' % (witness(t + 'a'), witness(t + 'b'))
    elif k < 0.4: body = 'for await (const x of input) { log("%s " + show(x)); %s yield %s; }' % (t, R.choice(['', '', 'await %s;' % wait()]), R.choice(['x', '[x]', '{ x }', 'show(x)']))
    elif k < 0.55: body = '%s yield* input; %s' % (R.choice(['', 'return', 'const r: any =']), R.choice(['', 'log("%s after");' % t]))
    elif k < 0.62: body = 'try { return yield* input; } finally { log("%s finally"); %s }' % (t, R.choice(['', '', 'await %s;' % wait()]))
    elif k < 0.7: body = 'const it = input[Symbol.asyncIterator](); for (;;) { const r = await it.next(); if (r.done) return r.value; %s yield r.value; }' % witness(t)
    elif k < 0.76: body = 'let n = 0; for await (const x of input) { if (n++ % 2) continue; yield x; }'
    elif k < 0.82: body = 'for await (const x of input) { yield x; yield x; }'
    elif k < 0.88: body = 'try { for await (const x of input) yield x; } catch (e) { log("%s caught " + (e as Error).message); yield "recovered"; }' % t
    elif k < 0.92: body = 'let n = 0; for await (const x of input) { if (++n === %d) throw new Error("%s threw"); yield x; }' % (R.randrange(1, 4), t)
    elif k < 0.96: body = 'let n = 0; for await (const x of input) { yield x; if (++n === %d) %s; }' % (R.randrange(1, 4), R.choice(['break', 'return "left"']))
    else: body = 'yield "first"; for await (const x of storage.run("%s", () => input)) yield x;' % t
    form = R.random()
    if form < 0.7:
        w('async function* %s(input: AsyncIterable<any>): AsyncGenerator<any, any, any> { %s }' % (name, body)); return '%s(%s)' % (name, inner)
    if form < 0.85:
        w('class %sClass { constructor(readonly input: AsyncIterable<any>) {} async *run(): AsyncGenerator<any, any, any> { const input = this.input; %s } [Symbol.asyncIterator]() { return this.run(); } }' % (name, body)); return 'new %sClass(%s)' % (name, inner)
    w('const %s = (input: AsyncIterable<any>): AsyncIterable<any> => ({ [Symbol.asyncIterator]: async function* () { %s } });' % (name, body)); return '%s(%s)' % (name, inner)
def pipeline():
    p = source()
    for _ in range(R.choice([0, 1, 1, 2, 2, 3, 3, 4, 5, 7])): p = layer(p)
    return p
def consumer():
    name = fresh('use'); p = pipeline(); t = name; k = R.random()
    stop = R.choice(['', '', '', '', 'if (n === %d) break;' % R.randrange(1, 4), 'if (n === %d) return "left";' % R.randrange(1, 4), 'if (n === %d) throw new Error("stop");' % R.randrange(1, 4)])
    inner = R.choice(['', '', '', 'await null;', 'await %s;' % wait(), witness(t + 'w')])
    if k < 0.7: body = 'let n = 0; for await (const x of %s) { n++; log("%s " + show(x)); %s %s }' % (p, t, stop, inner)
    elif k < 0.8: body = 'const it = %s[Symbol.asyncIterator](); const all = [it.next(), it.next("b"), it.next("c")]; %s for (const r of all) log("%s " + show(await r));' % (p, witness(t + 'q'), t)
    elif k < 0.88: body = 'const it = %s[Symbol.asyncIterator](); for (;;) { const r = await it.next("sent"); log("%s " + show(r)); if (r.done) break; %s }' % (p, t, inner)
    elif k < 0.94: body = 'const it = %s[Symbol.asyncIterator](); log("%s " + show(await it.next())); const r = it.return?.("early"); %s log("%s " + show(await r)); log("%s " + show(await it.next()));' % (p, t, witness(t + 'r'), t, t)
    else: body = 'const it = %s[Symbol.asyncIterator](); log("%s " + show(await Promise.race([it.next(), immediate("slow")]))); log("%s " + show(await it.next()));' % (p, t, t)
    w('async function %s(): Promise<any> { %s try { %s } catch (e) { log("%s caught " + (e as Error).message); } log("%s done"); return "%s"; }' % (name, R.choice(['', '', 'await null;', 'await immediate();']), body, t, t, t))
    return name
scenes = []
for s in range(10):
    users = [consumer() for _ in range(R.choice([1, 1, 1, 2, 3]))]
    start = []
    for i, u in enumerate(users):
        start.append(R.choice(['', '', '', 'ticks("t%d.", %d);' % (s, R.randrange(2, 9)), 'queueMicrotask(() => log("between"));']))
        call = '%s()' % u if R.random() < 0.6 else 'storage.run("c%d", %s)' % (i, u)
        start.append('running.push(%s.then(v => log("-> " + show(v)), e => log("-> rejected " + (e as Error).message)));' % call)
    w('async function scene%d() { const running: Promise<any>[] = []; %s await settle(running); }' % (s, ' '.join(x for x in start if x)))
    scenes.append('scene%d' % s)
w('for (const [i, scene] of [%s].entries()) { lines = []; await scene(); console.log("scene " + i + ": " + lines.join(" | ")); }' % ', '.join(scenes))
print('\n'.join(out))
